def classify_hit_type(line_text, full_line):
    """Classify the hit type based on context."""
    stripped = full_line.strip()
    filepath = line_text.split(':')[0] if ':' in line_text else ''

    # Proto-specific
    if filepath.endswith('.proto'):
        if any(kw in stripped for kw in ['package ', 'service ', 'message ', 'rpc ', 'syntax ']):
            return 'proto'
        if stripped.startswith('///') or stripped.startswith('//'):
            return 'proto-comment'
        return 'proto'

    # Comments (all languages)
    if stripped.startswith('//!') or stripped.startswith('///') or stripped.startswith('//'):
        return 'comment'
    if '//' in stripped and stripped.index('//') < stripped.index('tched') if 'tched' in stripped else stripped.index('//') < stripped.index('THREE') if 'THREE' in stripped else True:
        # Check if the line is predominantly a comment
        code_part = stripped.split('//')[0]
        if not code_part.strip() or code_part.strip().startswith('#'):
            return 'comment'

    # Module declarations
    if re.match(r'(pub\s+)?mod\s+\w*?(tched|threetched|3tched|TCHED)', stripped):
        return 'module'
    if 'include_proto!' in stripped:
        return 'module'
    if re.match(r'pub\s+use\s+.*(?:tched_router|tched_router_runtime)', stripped):
        return 'module'
    if re.match(r'pub\s+use\s+.*(?:TchedRouter|run_tched)', stripped):
        return 'module'

    # Struct/enum/impl/const definitions
    if re.match(r'(pub\s+)?struct\s+\w*?(tched|Threetched|Tched)', stripped):
        return 'identifier'
    if re.match(r'(pub\s+)?enum\s+\w*?(tched|Threetched|Tched)', stripped):
        return 'enum'
    if re.match(r'(pub\s+)?impl\s+\w*?(tched|Threetched|Tched)', stripped):
        return 'identifier'
    if re.match(r'const\s+.*(?:TCHED|tched)', stripped):
        return 'const'

    # Error types
    if re.search(r'#\[error.*\]', full_line) or re.search(r'error\(".*[Tt]ched', full_line):
        return 'error'

    # Function definitions
    if re.match(r'(pub\s+)?(async\s+)?fn\s+\w*?(tched|Threetched|Tched)', stripped):
        return 'function'

    # Env vars (TCHED_ROUTER_*)
    if re.search(r'(?:const\s+|let\s+)?.*TCHED_ROUTER_', stripped) and ('env::var' in stripped or 'VAR' in stripped):
        return 'env_var'
    if re.search(r'"TCHED_ROUTER_', stripped):
        return 'env_var'

    # Use statements referencing tched types
    if 'use ' in stripped and re.search(r'\btched_router\b|\bTchedRouter\b|\bthreetched\b|\bTCHED\b', stripped):
        return 'module'

    # Test assertions with string comparisons
    if re.match(r'\s*assert.*["\'].*[Tt]ched', stripped):
        return 'string'
    if re.match(r'\s*assert_eq.*["\'].*[Tt]ched', stripped):
        return 'string'

    # Anyline containing TCHED_ROUTER env var names
    if 'TCHED_ROUTER_' in stripped:
        return 'env_var'

    # Plugin ID string literals (e.g., "tched_router", "threetched")
    if re.search(r'"(?:tched_router|threetched|3tched)"', stripped):
        return 'string'

    # API endpoint / error messages containing tched
    if re.search(r'(?:anyhow|format!|tracing::|tracing::|println).*(?:[Tt]ched)', stripped):
        return 'string'

    # Default: identifier
    return 'identifier'


def extract_context(lines, hit_line_idx):
