                    "classify_all": user_msg
                }
            }

            try:
                req = Request(
                    LITELLM_URL,
                    json.dumps(payload).encode(),
                    {"Content-Type": "application/json", "Authorization": f"Bearer {LITELLM_API_KEY}"},
                    method='POST'
                )
                with urlopen(req, timeout=120) as resp:
                    data = json.loads(resp.read().decode())

                # Try to extract results
                content = ""
                if isinstance(data, dict):
                    content = data.get("message", {}).get("content", "")
                    if not content:
                        content = json.dumps(data)

                # Try to parse JSON responses from the batch
                # The response should contain JSON objects for each hit
                # Look for arrays of classification objects
                json_matches = re.findall(
                    r'\{[^{}]*"(classification|action)[^{}]*\}',
                    content, re.DOTALL
                )

                if not json_matches:
                    # Try broader: find all JSON objects
                    all_objects = []
                    depth = 0
                    start = None
                    for i, ch in enumerate(content):
                        if ch == '{':
                            if depth == 0:
                                start = i
                            depth += 1
                        elif ch == '}':
                            depth -= 1
                            if depth == 0 and start is not None:
                                try:
                                    obj = json.loads(content[start:i+1])
                                    all_objects.append(obj)
                                except:
                                    pass
                                start = None

                if len(all_objects) >= len(batch):
                    # Assign each object to its hit
                    for j, (idx, hit) in enumerate(batch):
                        if j < len(all_objects):
                            results[idx] = all_objects[j]
                    print(f"  Batch {batch_idx+1}/{len(batches)}: parsed {len(all_objects)} classifications", file=sys.stderr)
                else:
                    print(f"  Batch {batch_idx+1}/{len(batches)}: got {len(all_objects)} objects (expected {len(batch)}), using defaults", file=sys.stderr)
                    # Use conservative defaults
                    for idx, hit in batch:
                        results[idx] = {
                            "classification": "C-UNRESOLVED",
                            "action": "report",
                            "reason": "JEV response parsing incomplete",
                            "jev_confidence": 0.0
                        }

                total_processed += len(batch)
                time.sleep(0.5)  # Rate limit

            except Exception as e:
                print(f"  Error in batch {batch_idx+1}: {e}", file=sys.stderr)
                for idx, hit in batch:
                    results[idx] = {
                        "classification": "C-UNRESOLVED",
                        "action": "report",
                        "reason": f"API error: {e}",
                        "jev_confidence": 0.0
                    }

    # Fill remaining with defaults
    for i, r in enumerate(results):
        if r is None:
            results[i] = {
                "classification": "C-UNRESOLVED",
                "action": "report",
                "reason": "No JEV response",
                "jev_confidence": 0.0
            }

    return results


def main():
    print("Parsing all tched hits...", file=sys.stderr)
    hits = parse_all_hits()
    print(f"Found {len(hits)} hits to classify", file=sys.stderr)

    # Quick sanity check - show distribution
    from collections import Counter
    type_dist = Counter(h["hit_type"] for h in hits)
    print(f"Hit type distribution: {dict(type_dist)}", file=sys.stderr)

    print("Classifying via JEV...", file=sys.stderr)
    judgments = classify_in_bulk(hits, batch_size=5)

    # Write JSONL output
    os.makedirs(os.path.dirname(OUTPUT), exist_ok=True)

    with open(OUTPUT, 'w') as f:
        for i, hit in enumerate(hits):
            judgment = judgments[i] if i < len(judgments) else {}

            line = {
                "file": hit["file"],
                "line": hit["line"],
                "text": hit["text"],
                "context_3_above": hit["context_3_above"],
                "context_3_below": hit["context_3_below"],
                "hit_type": hit["hit_type"],
                "jev_input": {
                    "file": hit["file"],
                    "line": hit["line"],
                    "text": hit["text"],
                    "hit_type": hit["hit_type"],
                    "tched_term": hit["tched_term"],
                    "context_3_above": hit["context_3_above"],
                    "context_3_below": hit["context_3_below"]
                },
                "classification": judgment.get("classification", "C-UNRESOLVED"),
                "action": judgment.get("action", "report"),
                "reason": judgment.get("reason", "JEV response missing"),
                "jev_confidence": judgment.get("jev_confidence", 0.0)
            }
            f.write(json.dumps(line) + "\n")

    print(f"Written {len(hits)} judgments to {OUTPUT}", file=sys.stderr)

    # Summary
    dist = Counter()
    for j in judgments:
        dist[j.get("classification", "unknown")] += 1

    print(f"Classification distribution: {dict(dist)}", file=sys.stderr)


if __name__ == "__main__":
    main()
"}

