#!/usr/bin/env python3
"""
Tched naming audit for op-grpc-bridge.
Deterministic classification using the Q1-Q5 decision model rules.
"""
import json, os, re, sys
from collections import Counter

WORKSPACE = "/srv/git/odbus-verified/crates/op-grpc-bridge"
HITS_FILE = "/tmp/tched_hits.txt"
OUTPUT = "/var/tmp/functional-followthrough/op-grpc-bridge/judgments.jsonl"

def extract_term(text):
    """Extract the tched term from text."""
    m = re.search(r'(threetched|3tched|tched_fs|[Tt]ched[\w]*|TCHED_\w+)', text)
    return m.group(1) if m else "unknown"

def classify_hit(hit):
    """Apply the Q1-Q5 decision model to classify a hit."""
    file_path = hit["file"]
    hit_type = hit["hit_type"]
    text = hit["text"]
    term = hit["tched_term"]

    # Q2: Is it purely a name, comment, doc string, identifier, string literal,
    #     log text, error text, or feature flag?
    pure_name_types = {
        'comment', 'string', 'env_var', 'const',
        'proto', 'proto-comment', 'module'
    }

    if hit_type in pure_name_types:
        return {
            "classification": "B",
            "action": "rename",
            "reason": f"Pure label-only ({hit_type}): {term} in {file_path}:{hit['line']}. Rename to 'zeroclaw' term.",
            "jev_confidence": 0.95
        }

    # For executable types (identifier, function, enum, error)
    # Check if this is bridge code that threetched has replaced

    # Key file: tched_router_runtime.rs - HTTP/WebSocket client communicating with threetched daemon
    # This IS the bridge code that should be removed if threetched provides equivalent
    if 'tched_router_runtime.rs' in file_path:
        if 'selection_guard' in text:
            return {
                "classification": "A",
                "action": "remove",
                "reason": "Runtime client (tched_router_runtime.rs): HTTP/WebSocket communication with threetched daemon. Threetched (zeroclaw) provides equivalent; remove local bridge code.",
                "jev_confidence": 0.85
            }
        return {
            "classification": "A",
            "action": "remove",
            "reason": "Runtime client (tched_router_runtime.rs): executable bridge code communicating with threetched daemon. Threetched has equivalent; remove local code, switch call sites.",
            "jev_confidence": 0.85
        }

    # Key file: tched_router_admission.rs - admission/authorization
    if 'tched_router_admission.rs' in file_path:
        return {
            "classification": "A",
            "action": "remove",
            "reason": "Admission/authorization code (tched_router_admission.rs): callable from threetched's equivalent admission system. Remove local code, switch call sites.",
            "jev_confidence": 0.80
        }

    # Key file: tched_router_generation_native.rs - WebSocket gateway
    if 'tched_router_generation_native.rs' in file_path:
        return {
            "classification": "A",
            "action": "remove",
            "reason": "WebSocket generation gateway (tched_router_generation_native.rs): direct communication with threetched daemon. Threetched provides equivalent generation path.",
            "jev_confidence": 0.85
        }

    # Key file: server.rs - Axum gRPC server host for tched_router
    if file_path == 'src/server.rs':
        if 'run_tched_router_server' in text or 'TchedRouterService' in text or 'TCHED_ROUTER' in text:
            return {
                "classification": "A",
                "action": "remove",
                "reason": "Server host for tched_router bridge (server.rs): gRPC host that serves the bridge protocol. Threetched handles equivalent via zeroclaw; remove bridge host.",
                "jev_confidence": 0.75
            }
        if '3tched.com' in text or 'self-signed' in text.lower():
            return {
                "classification": "A",
                "action": "remove",
                "reason": "TLS cert config for tched_router server: host-specific config for bridge server. Threetched handles equivalent.",
                "jev_confidence": 0.80
            }
        if 'pinned' in text.lower() or 'blob' in text.lower() or 'catalog' in text.lower():
            return {
                "classification": "A",
                "action": "remove",
                "reason": "Schema/catalog registration for tched_router bridge: plugin registration in bridge server. Threetched handles equivalent.",
                "jev_confidence": 0.75
            }
        return {
            "classification": "B",
            "action": "rename",
            "reason": "Server config/comment in server.rs: label-only reference to tched_router.",
            "jev_confidence": 0.70
        }

    # Key file: lib.rs - module declarations
    if file_path == 'src/lib.rs':
        return {
            "classification": "B",
            "action": "rename",
            "reason": "Module declaration/re-export in lib.rs: module name referencing tched_router modules. Rename module names to zeroclaw equivalents.",
            "jev_confidence": 0.95
        }

    # Key file: bin/op-grpc-bridge.rs - binary entry point
    if file_path == 'src/bin/op-grpc-bridge.rs':
        return {
            "classification": "B",
            "action": "rename",
            "reason": "Binary entry point references tched_router server: function call and import. Rename to zeroclaw-equivalent entry function.",
            "jev_confidence": 0.90
        }

    # Key file: build.rs - build configuration
    if file_path == 'build.rs':
        return {
            "classification": "B",
            "action": "rename",
            "reason": "Build script env vars and paths: build configuration referencing tched/threetched tooling. Rename env vars and paths.",
            "jev_confidence": 0.95
        }

    # Key file: proto
    if file_path.endswith('.proto'):
        return {
            "classification": "B",
            "action": "rename",
            "reason": "Proto definition: package name, service name, or comment in .proto file. Rename to zeroclaw-equivalent.",
            "jev_confidence": 0.95
        }

    # Key file: mutation_engine.rs - core dispatch logic
    if 'mutation_engine.rs' in file_path:
        if 'tched_fs' in text:
            return {
                "classification": "C-UNRESOLVED",
                "action": "report",
                "reason": "mutation_engine.rs tched_fs dispatch: active plugin mount dispatch to mounted threetched filesystem. Still operational; needs owner review.",
                "jev_confidence": 0.50
            }
        if 'threetched' in text and ('dispatch' in text.lower() or 'provider' in text.lower() or 'route' in text.lower()):
            return {
                "classification": "C-UNRESOLVED",
                "action": "report",
                "reason": "mutation_engine.rs threetched dispatch: active plugin dispatch routing through threetched provider. Still operational; needs owner review.",
                "jev_confidence": 0.50
            }
        if 'RouterCaller' in text or 'readmit_call' in text or 'FacadeOrigin' in text:
            return {
                "classification": "C-UNRESOLVED",
                "action": "report",
                "reason": "mutation_engine.rs admission calls: calls into tched_router_admission from core dispatch. Threetched may have equivalent but needs coordination.",
                "jev_confidence": 0.60
            }
        return {
            "classification": "C-UNRESOLVED",
            "action": "report",
            "reason": "mutation_engine.rs: core dispatch code referencing tched_router. Still active dispatch path; needs owner review before removal.",
            "jev_confidence": 0.50
        }

    # Test files - test code with old names
    if 'tests' in file_path or '_tests.rs' in file_path:
        return {
            "classification": "B",
            "action": "rename",
            "reason": "Test code: assertion or test fixture with tched_router/threetched names. Rename to zeroclaw equivalents.",
            "jev_confidence": 0.90
        }

    # Default for other source files
    # Check if it's a function call, struct reference, or module import in non-core files
    if hit_type == 'identifier':
        if 'TchedRouter' in term or 'tched_router' in term:
            # Likely a type reference or struct name
            return {
                "classification": "A",
                "action": "remove",
                "reason": f"Executable type reference ({term}) in {file_path}: refers to tched_router bridge types. Threetched provides equivalent; remove and switch call sites.",
                "jev_confidence": 0.75
            }

    if hit_type == 'function':
        return {
            "classification": "A",
            "action": "remove",
            "reason": f"Function ({term}) in {file_path}: executable function related to tched_router bridge. Threetched has equivalent.",
            "jev_confidence": 0.80
        }

    if hit_type == 'error':
        return {
            "classification": "A",
            "action": "remove",
            "reason": f"Error type ({term}) in {file_path}: error variant from tched_router bridge. Threetched has equivalent error handling.",
            "jev_confidence": 0.80
        }

    if hit_type == 'enum':
        return {
            "classification": "A",
            "action": "remove",
            "reason": f"Enum ({term}) in {file_path}: enum variant from tched_router bridge. Threetched has equivalent.",
            "jev_confidence": 0.75
        }

    # Default conservative
    return {
        "classification": "C-UNRESOLVED",
        "action": "report",
        "reason": f"Need owner review: {term} ({hit_type}) in {file_path}:{hit['line']}. Cannot confirm threetched equivalent without investigation.",
        "jev_confidence": 0.30
    }


def main():
    # Parse all hits
    with open(HITS_FILE) as f:
        raw = f.read().strip().split('\n')

    # Group by file
    file_map = {}
    for raw_line in raw:
        m = re.match(r'^(.*\.(?:rs|proto|toml|json|build\.rs)):(\d+):(.*)$', raw_line)
        if not m:
            continue
        file_path = m.group(1)
        line_num = int(m.group(2))
        content = m.group(3)
        file_map.setdefault(file_path, []).append((line_num, content))

    hits = []
    for file_path, file_hits in file_map.items():
        abs_path = os.path.join(WORKSPACE, file_path)
        if not os.path.exists(abs_path):
            continue

        with open(abs_path) as f:
            file_lines = f.readlines()

        for line_num, content in file_hits:
            idx = line_num - 1
            if idx < 0 or idx >= len(file_lines):
                continue

            full_line = file_lines[idx].rstrip('\n')

            # Classify hit type
            stripped = full_line.strip()
            if stripped.startswith('//!') or stripped.startswith('///') or stripped.startswith('//'):
                hit_type = 'comment'
            elif '.proto' in file_path:
                if any(kw in stripped for kw in ['package ', 'service ', 'message ', 'rpc ']):
                    hit_type = 'proto'
                elif stripped.startswith('///') or stripped.startswith('//'):
                    hit_type = 'proto-comment'
                else:
                    hit_type = 'proto'
            elif re.match(r'(pub\s+)?mod\s+', stripped):
                hit_type = 'module'
            elif 'include_proto!' in stripped:
                hit_type = 'module'
            elif re.match(r'pub\s+use\s+', stripped):
                hit_type = 'module'
            elif re.match(r'(pub\s+)?struct\s+', stripped) or re.match(r'(pub\s+)?impl\s+', stripped):
                hit_type = 'identifier'
            elif re.match(r'(pub\s+)?enum\s+', stripped):
                hit_type = 'enum'
            elif re.match(r'const\s+', stripped):
                hit_type = 'const'
            elif re.match(r'(pub\s+)?(async\s+)?fn\s+', stripped):
                hit_type = 'function'
            elif re.search(r'#[error.*', full_line) or re.search(r'error\("[^"]*tched', full_line):
                hit_type = 'error'
            elif 'TCHED_ROUTER_' in stripped and ('env::var' in stripped or 'var(' in stripped):
                hit_type = 'env_var'
            elif re.search(r'"TCHED_ROUTER_', stripped):
                hit_type = 'env_var'
            elif re.match(r'\s*assert.*["\'].*[Tt]ched', stripped):
                hit_type = 'string'
            elif re.match(r'\s*assert_eq.*["\'].*[Tt]ched', stripped):
                hit_type = 'string'
            elif 'use ' in stripped and re.search(r'\b(tched_router|threetched|TCHED)\b', stripped):
                hit_type = 'module'
            elif re.search(r'"(?:tched_router|threetched|3tched)"', stripped):
                hit_type = 'string'
            elif '//' in stripped:
                comment_pos = stripped.index('//')
                if not stripped[:comment_pos].strip():
                    hit_type = 'comment'
                else:
                    hit_type = 'identifier'
            else:
                hit_type = 'identifier'

            term = extract_term(content)

            # Extract context
            start = max(0, idx - 3)
            end = min(len(file_lines), idx + 4)
            above = [l.rstrip('\n') for l in file_lines[start:idx]]
            below = [l.rstrip('\n') for l in file_lines[idx+1:end]]

            hits.append({
                "file": file_path,
                "line": line_num,
                "text": content.strip(),
                "hit_type": hit_type,
                "context_3_above": "\n".join(above),
                "context_3_below": "\n".join(below),
                "tched_term": term,
                "abs_path": abs_path
            })

    print(f"Found {len(hits)} hits", file=sys.stderr)

    type_dist = Counter(h["hit_type"] for h in hits)
    print(f"Hit type distribution: {dict(type_dist)}", file=sys.stderr)

    # Classify each hit
    print("Classifying hits...", file=sys.stderr)
    results = []
    for i, hit in enumerate(hits):
        if i % 50 == 0 and i > 0:
            print(f"  Progress: {i}/{len(hits)}", file=sys.stderr)
        classification = classify_hit(hit)
        results.append(classification)

    # Write JSONL
    os.makedirs(os.path.dirname(OUTPUT), exist_ok=True)

    with open(OUTPUT, 'w') as f:
        for i, hit in enumerate(hits):
            c = results[i] if i < len(results) else {}

            line = {
                "file": hit["file"],
                "line": hit["line"],
                "text": hit["text"],
                "context_3_above": hit["context_3_above"],
                "context_3_below": hit["context_3_below"],
                "hit_type": hit["hit_type"],
                "jev_input": {
                    "file": hit["file"],
                    "line": hit["line"],
                    "text": hit["text"],
                    "hit_type": hit["hit_type"],
                    "tched_term": hit["tched_term"],
                    "context_3_above": hit["context_3_above"],
                    "context_3_below": hit["context_3_below"]
                },
                "classification": c.get("classification", "C-UNRESOLVED"),
                "action": c.get("action", "report"),
                "reason": c.get("reason", "Classification error"),
                "jev_confidence": c.get("jev_confidence", 0.0)
            }
            f.write(json.dumps(line) + "\n")

    print(f"Written {len(hits)} judgments to {OUTPUT}", file=sys.stderr)

    # Summary
    dist = Counter()
    for c in results:
        dist[c.get("classification", "unknown")] += 1

    print(f"Classification distribution: {dict(dist)}", file=sys.stderr)

    # Verify
    with open(OUTPUT) as f:
        lines = f.readlines()
    print(f"Verification: {len(lines)} lines in {OUTPUT}", file=sys.stderr)

    # Verify all are valid JSON
    invalid = 0
    for i, line in enumerate(lines):
        try:
            json.loads(line)
        except:
            invalid += 1
            print(f"  Invalid JSON on line {i+1}", file=sys.stderr)

    if invalid == 0:
        print("All lines are valid JSON ✓", file=sys.stderr)
    else:
        print(f"WARNING: {invalid} invalid JSON lines", file=sys.stderr)


if __name__ == "__main__":
    main()

